import{_ as t,c as s,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Employees setup","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/index.md","filePath":"master/human-resources/employees/setup/index.md","lastUpdated":1792041590000}'),r={name:"master/human-resources/employees/setup/index.md"};function n(l,e,i,p,d,h){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="employees-setup" tabindex="-1">Employees setup <a class="header-anchor" href="#employees-setup" aria-label="Permalink to &quot;Employees setup&quot;">​</a></h1><p>Setup is the set of small lists that feed the employee form. They give you the choices for a job, a work place, a tag or a reason for leaving. You create each list once, then pick from it whenever you add or edit an employee.</p><blockquote><p><strong>In simple words:</strong> Setup lists are the drop-down choices that employees, departments and positions use.</p></blockquote><p>Open <code>Employees → Configurations</code>. The left menu has three parts:</p><ul><li>No heading: <strong>Activity Plans</strong></li><li><strong>Employee</strong>: <strong>Departure Reasons</strong>, <strong>Tags</strong>, <strong>Work Locations</strong>, <strong>Skill Types</strong></li><li><strong>Recruitment</strong>: <strong>Employment Types</strong>, <strong>Job Positions</strong></li></ul><h2 id="how-the-records-relate" tabindex="-1">How the records relate <a class="header-anchor" href="#how-the-records-relate" aria-label="Permalink to &quot;How the records relate&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Department ──►  Job Position  ◄── Employment Type</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span> Work Location ──► Employee ◄── Tags</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>          Skill Type ─┤</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>              Departure Reason (when the person leaves)</span></span></code></pre></div><ul><li>A <strong>job position</strong> belongs to a department and can name an employment type.</li><li>An <strong>employee</strong> picks a department, a job position, a work location and tags.</li><li><strong>Skill types</strong> hold the skills and levels you add to an employee.</li><li>A <strong>departure reason</strong> is chosen when the person leaves.</li><li><strong>Activity plans</strong> are checklists of tasks, such as onboarding.</li></ul><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./job-positions.html">Job positions</a></td><td>Roles in your company, with department and description</td></tr><tr><td><a href="./employment-types.html">Employment types</a></td><td>Labels such as Full-Time or Intern</td></tr><tr><td><a href="./work-locations.html">Work locations</a></td><td>Office, home or other places people work from</td></tr><tr><td><a href="./tags.html">Tags</a></td><td>Coloured labels you attach to employees</td></tr><tr><td><a href="./departure-reasons.html">Departure reasons</a></td><td>Why a person left</td></tr><tr><td><a href="./skill-types.html">Skill types</a></td><td>Groups of skills and their levels</td></tr><tr><td><a href="./activity-plans.html">Activity plans</a></td><td>Task checklists for onboarding and offboarding</td></tr></tbody></table><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><ol><li>Check the sample lists. Many companies can use them as they are.</li><li>Create your departments. See <a href="./../departments/departments.html">Departments</a>.</li><li>Create job positions for each role.</li><li>Add the tags and work locations you need.</li><li>Add employees.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most simple lists open in a window. Click <strong>Create &amp; create another</strong> to add several records quickly.</p></div><h2 id="common-list-features" tabindex="-1">Common list features <a class="header-anchor" href="#common-list-features" aria-label="Permalink to &quot;Common list features&quot;">​</a></h2><p>Every list has a search box, a filter button, a column manager and a <strong>Group</strong> option. Rows have <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. You can select rows to act on several at once.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Employees overview</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li></ul>`,17)]))}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
